window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"EBn9gBA4Ow4","speaker":"Mohamed Irfaan Ali","role":"President","country":"Guyana","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=EBn9gBA4Ow4","date":"20260924","title":"🇬🇾 Guyana - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1394,"words":2514,"counts":{"claims":33,"promises":0,"attacks":0},"topics":[{"topic":"UN leadership","share":0.2406,"seconds":336},{"topic":"UN reform","share":0.2209,"seconds":308},{"topic":"Multilateralism","share":0.093,"seconds":130},{"topic":"Cuba","share":0.0622,"seconds":87},{"topic":"Guyana biodiversity","share":0.0543,"seconds":76},{"topic":"Venezuela","share":0.0523,"seconds":73},{"topic":"Sustainable development","share":0.0481,"seconds":67},{"topic":"Regional security","share":0.0472,"seconds":66},{"topic":"Indigenous rights","share":0.0464,"seconds":65},{"topic":"AI technology","share":0.0459,"seconds":64},{"topic":"Middle East","share":0.0458,"seconds":64},{"topic":"Global cooperation","share":0.0433,"seconds":60}],"timeline":[[2,65,null],[67,144,"UN leadership"],[145,235,"UN reform"],[235,296,"Global cooperation"],[298,362,"Middle East"],[363,450,"Cuba"],[451,524,"Venezuela"],[525,591,"Regional security"],[592,656,"AI technology"],[657,724,"Sustainable development"],[726,802,"Guyana biodiversity"],[803,884,"UN reform"],[884,953,"Multilateralism"],[956,1020,"UN reform"],[1021,1094,"UN reform"],[1096,1159,"UN leadership"],[1161,1229,"UN leadership"],[1231,1295,"Indigenous rights"],[1297,1358,"UN leadership"],[1360,1425,"UN leadership"],[1426,1487,"Multilateralism"],[1488,1537,null]],"stances":{"UN leadership":"Mohamed Irfaan Ali expresses deep appreciation for Secretary-General Antonio Guterres's service and principles while emphasizing the UN's need to confront aggression.","UN reform":"Mohamed Irfaan Ali argues that the United Nations must undertake bold institutional reforms to strengthen its credibility and address global challenges.","Global cooperation":"Mohamed Irfaan Ali asserts that collective action and inventiveness have historically resolved major global crises and should be the focus for future solutions.","Middle East":"Mohamed Irfaan Ali calls for a just and lasting solution to the Middle East crisis that ends civilian suffering and recognizes Palestinian rights.","Cuba":"Mohamed Irfaan Ali calls for a peaceful, people-centered, and development-focused viable solution for Cuba that realizes the full aspirations of its people.","Venezuela":"Mohamed Irfaan Ali states that Guyana has participated in the ICJ proceedings and urges Venezuela to abide by the forthcoming ruling while expressing a desire for improved neighborly relations.","Regional security":"Mohamed Irfaan Ali states that Guyana is a founding member of the initiative and emphasizes collective responsibility to fight transnational crime through partnership.","AI technology":"Mohamed Irfaan Ali argues that technological progress should be measured by the empowerment of people rather than machine power and must not be limited to a privileged few.","Sustainable development":"Mohamed Irfaan Ali argues that sustainable development must be treated as a binding covenant to ensure inclusive prosperity and must be integrated into national strategies, policies, and budgets.","Guyana biodiversity":"Mohamed Irfaan Ali states that Guyana has made significant advances in national priorities and established the Global Biodiversity Alliance to provide global leadership on biodiversity.","Multilateralism":"Mohamed Irfaan Ali argues that multilateralism must be reclaimed and renewed to address global wars, existential threats, and inequality.","Indigenous rights":"The speaker describes an indigenous woman as someone who has overcome significant barriers related to gender, poverty, and origin to achieve success."},"claims":[{"t":67,"quote":"I take this opportunity to record Guyana's gratitude to the Secretary General, his excellency Antonio Gutterz for his distinguished service to the United Nations and to the cause of humanity.","topic":"UN leadership","kind":"fact"},{"t":119,"quote":"Mr. President, one year ago, I stood at this very podium and reminded this assembly that if the United Nations is to remain humanity's shest hope for a just and peaceful world, it must have the courage to confront aggression and the well and the will to engage fully with the defining question of our age.","topic":"UN leadership","kind":"self_credit"},{"t":168,"quote":"restoring trust, managing transformation, a United Nations that delivers for all","topic":"UN reform","kind":"fact"},{"t":188,"quote":"Today we confront a climate catastrophe and energy crisis, food insecurity, biodiversity loss, armed conflicts, and geopolitical tensions","topic":"UN reform","kind":"fact"},{"t":237,"quote":"We have ended wars that seem without end. We have confronted economic calamities that threatened the foundations of societies. We have overcome dangers that presented existential threats.","topic":"Global cooperation","kind":"fact"},{"t":307,"quote":"The world does not need more sophisticated instruments of destruction. It needs a more sophisticated capacity for peace.","topic":"Middle East","kind":"fact"},{"t":431,"quote":"Despite the historical truth clearly outlined in the arbitral award of 1899 that determined the full perfect and final settlement of our border with Venezuela","topic":"Cuba","kind":"fact"},{"t":451,"quote":"The matter was referred to the international court of justice by the secretary general acting pursuant to the Geneva agreement and the court twice pronounced on his jurisdiction to hear the matter.","topic":"Venezuela","kind":"fact"},{"t":466,"quote":"Recourse to the ICJ came after decades of efforts to resolve the controversy bilaterally, including through a mixed commission and the good offices of the UN Secretary General.","topic":"Venezuela","kind":"fact"},{"t":492,"quote":"Now that we have both participated in the hearings which were completed in May we urge Venezuela to abide by the forthcoming ruling in accordance with obl their obligation under the UN charter as Guyana will do.","topic":"Venezuela","kind":"fact"},{"t":531,"quote":"Guyana is honored to be a founding member of the Shield of the Americas, launched by President Trump in March 2026.","topic":"Regional security","kind":"fact"},{"t":541,"quote":"Since the founding of this initiative, Guyana has worked closely with the United States and 13 other like-minded nations","topic":"Regional security","kind":"fact"},{"t":618,"quote":"Artificial intelligence, digital communications, and other extraordinary breakthroughs offer the prospect of transforming health, education, agriculture, productivity, and public services on a scale scarcely imaginable a generation ago.","topic":"AI technology","kind":"fact"},{"t":657,"quote":"It must become the servant of all Mr. President, we have before us a new opportunity for sustainable development.","topic":"Sustainable development","kind":"fact"},{"t":704,"quote":"One way to arrest the slippage is as Guyana is doing to mainstream the goals into our national development strategies, public policies and budgets so that they become embedded in the priorities we set and the resources we commit rather than remaining aspirations.","topic":"Sustainable development","kind":"self_credit"},{"t":734,"quote":"In we have made significant advances, including universal health care, free education, modern infrastructure, accelerated access to affordable housing, opportunities for full employment, acceleration of financing for small and medium-siz enterprises, and digitizing service delivery.","topic":"Guyana biodiversity","kind":"fact"},{"t":769,"quote":"In July 2025, under Guyana's leadership, the Global Biodiversity Alliance was established as an inclusive platform.","topic":"Guyana biodiversity","kind":"fact"},{"t":779,"quote":"In just one year, the alliance expanded from 17 to 138 members, bringing together governments, institutional including the UN, development banks, indigenous peoples, local communities, scientists, universities, and the private sector.","topic":"Guyana biodiversity","kind":"number"},{"t":803,"quote":"The second conference of the of the alliance to be held in October 2026 will begin to mobilize the resources and partnerships to deliver its ambitions.","topic":"UN reform","kind":"fact"},{"t":816,"quote":"we continue to advance our lowcarbon development strategy focused on turning forest stewardship and climate action into a new model for sustainable development.","topic":"UN reform","kind":"fact"},{"t":901,"quote":"when wars rage across borders, when the shadow of existential threats falls across the future of human civilization","topic":"Multilateralism","kind":"fact"},{"t":949,"quote":"no just international order when rules are applied selectively","topic":"Multilateralism","kind":"fact"},{"t":969,"quote":"The world has changed and multilateralism must change with it.","topic":"UN reform","kind":"fact"},{"t":975,"quote":"We need a new and invigorated multilateralism. One equal to the turbulence of our age.","topic":"UN reform","kind":"fact"},{"t":1021,"quote":"We must bring greater coherence to a system too often divided by institutional rivalries, bureaucratic silos, and competing mandates.","topic":"UN reform","kind":"fact"},{"t":1040,"quote":"But institutions do not reform They require leadership capable of seeing beyond the present and imagining the institutions the future demands.","topic":"UN reform","kind":"fact"},{"t":1146,"quote":"She has served her represented the developing world, and worked within the multilateral system with a deep understanding of both its promise and its imperfections.","topic":"UN leadership","kind":"fact"},{"t":1161,"quote":"We believe that her experience, her convictions, her record of service speak directly to the kind of leadership this moment demands.","topic":"UN leadership","kind":"fact"},{"t":1244,"quote":"an indigenous woman coming from a small indigenous village defying the odds, the odds against persons, the odds against women, the odds against poverty.","topic":"Indigenous rights","kind":"fact"},{"t":1314,"quote":"You know her character. You know her integrity. You know her will. You know her commitment. You know her love for humanity. You know her love for this world.","topic":"UN leadership","kind":"fact"},{"t":1331,"quote":"I know that this world will be a better place with Carlin Rodrig as the Secretary General of the United Nations.","topic":"UN leadership","kind":"fact"},{"t":1364,"quote":"Caricom as a body has endorsed her","topic":"UN leadership","kind":"fact"},{"t":1390,"quote":"The responsibility for recommending the next secretary general rests in the forest instance with the security council","topic":"UN leadership","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"The assembly will now hear an address by his excellency Muhammad Van Ali, President of the Cooperative Republic of I request protocol to escort his excellency and invite him to address the Mr. President, I extend my congratulations on your election as president of the 81st session of the General Assembly. I wish you every success as you undertake this important responsibility at a moment when multilateralism and indeed the United Nations faces profound I also express my sincere appreciation to your predecessor for her stewardship over the past year."},{"t":67,"topic":"UN leadership","text":"I take this opportunity to record Guyana's gratitude to the Secretary General, his excellency Antonio Gutterz for his distinguished service to the United Nations and to the cause of humanity. His place in the history of this institution is assured not mereily by the office he has occupied but by the principles he has steadfastly upheld. The courage and profoundity with which he has spoken when silence would have been easier. and his rare ability to hold before the world a clear mirror of the perils that confront our age and the possibilities that still beckon beyond them. Mr. President, one year ago, I stood at this very podium and reminded this assembly that if the United Nations is to remain humanity's shest hope for a just and peaceful world, it must have the courage to confront aggression and the well and the will to engage fully with the defining question of our age."},{"t":145,"topic":"UN reform","text":"I also argued that we must be bold enough to undertake the institutional reforms necessary to strengthen the enhance its credibility and enable it to meet the challenges of a changing world. Indeed, I am pleased that the theme of this year assembly, and I quote, restoring trust, managing transformation, a United Nations that delivers for all, end of quote, acknowledges the need for this organization to be fit for purpose, to respond to the challenges, and to seize the possibilities of our time. Today we confront a climate catastrophe and energy crisis, food insecurity, biodiversity loss, armed conflicts, and geopolitical tensions. The horror of genocide, a spiraling cost of living crisis, a mountain death crisis, widening inequalities within and among nations, and perhaps most troubling of all, a weakening of multilateralism Yet if history has taught us anything, it is that when it is that even when the world seemed to stand at the precipice, humanity has never been entirely without the means to draw it"},{"t":235,"topic":"Global cooperation","text":"back from the brink. We have ended wars that seem without end. We have confronted economic calamities that threatened the foundations of societies. We have overcome dangers that presented existential threats. Time and again, it has been our inventiveness, our courage, and above all, our willingness to act together that have opened the path where none seemed to exist. This is why I do not wish to linger or lament further upon the difficulties before us. I wish instead to turn our gaze toward the possibilities that lie beyond them. For within every crisis lies a summons to solutions. Within every disruption and opportunity for renewal and within every uncertainty the possibility of shaping a better future."},{"t":298,"topic":"Middle East","text":"The possibility before us are immense. We have the possibility of silencing the guns through dialogue and diplomacy. The world does not need more sophisticated instruments of destruction. It needs a more sophisticated capacity for peace. In this regard, I reiterate Guyana's call for a just and lasting solution to the crisis in the Middle East. One that brings an end to the suffering of innocent civilians and recognizes the Palestinian people's legitimate right to and to secure homeland of their own. Reiterate our support for a two-state We call as well for an end to the Russia Ukraine war and the war in Sudan and for peaceful resolution of all conflicts that continue to consume lives, uproot families and extinguish the hopes of millions in other parts of our world."},{"t":363,"topic":"Cuba","text":"We reiterate our call for a viable solution for Cuba, one that is peaceful, people centered, development focused, and allows for the full aspiration of the Cuban people to be realized. Guy reiterates Cariccom's offer to play a meaningful role in achieving this in Haiti. re re resolving the multi-dimensional challenges remains central to achieving democracy, stability, peace, and prosperity for the Haitian people. The sustained support of the international community through the provision of key financial and material resources is critical to realizing these objectives. Ultimately, the future of Haiti must be Haitianled and Haitian owned. Mr. President, turning to my own country, Guyana's always advanced the peaceful settlement of the controversy in relation to our border with Despite the historical truth clearly outlined in the arbitral award of 1899 that determined the full perfect and final settlement of our border with Venezuela, we endured long and repeated provocations and aggression."},{"t":451,"topic":"Venezuela","text":"The matter was referred to the international court of justice by the secretary general acting pursuant to the Geneva agreement and the court twice pronounced on his jurisdiction to hear the matter. Recourse to the ICJ came after decades of efforts to resolve the controversy bilaterally, including through a mixed commission and the good offices of the UN Secretary General. In full respect for international law, Guyana participated and encouraged Venezuela to participate in the proceedings of the Now that we have both participated in the hearings which were completed in May we urge Venezuela to abide by the forthcoming ruling in accordance with obl their obligation under the UN charter as Guyana will do. We look forward to a new era of neighborly relations in the interests of our peoples, the development of our countries, and the stability and prosperity of our region."},{"t":525,"topic":"Regional security","text":"Mr. President, in pursuit of a stronger and safer region, Guyana is honored to be a founding member of the Shield of the Americas, launched by President Trump in March 2026. Since the founding of this initiative, Guyana has worked closely with the United States and 13 other like-minded nations that believe in building a western hemisphere that values freedom, peace, economic prosperity, and a shared responsibility and commitment to fighting transnational crime and criminal networks. It is it is our collective responsibility to never allow our region to be overtaken by gangs or criminal networks. We understand that is it that is that it is only through partnership, shared intelligence and cooperation that we can effectively tackle the threats they pose to our economies and the livelihoods of our citizens."},{"t":592,"topic":"AI technology","text":"This week, I am pleased to join members of the Shield of Americas in adopting a joint communicate which underscores our collective resolve to strengthen the resilience of our region in economic security and multilateral Mr. President, we stand at the threshold of a new era of technological advancement. Artificial intelligence, digital communications, and other extraordinary breakthroughs offer the prospect of transforming health, education, agriculture, productivity, and public services on a scale scarcely imaginable a generation ago. But a true measure of technological progress will not be how powerful our machines become, but how much more empowered our people become. Technology must not become the privilege of the few."},{"t":657,"topic":"Sustainable development","text":"It must become the servant of all Mr. President, we have before us a new opportunity for sustainable development. Development must not merely make our economies richer. It must make our societies better. We must not allow for the slippage in our pursuit of the sustainable development goals. We must renew our commitment to them not as an inventory of promises but as a covenant with our people's and practical blueprint for ensuring the development reaches every citizen. protects generations yet unborn and creates lasting inclusive prosperity. One way to arrest the slippage is as Guyana is doing to mainstream the goals into our national development strategies, public policies and budgets so that they become embedded in the priorities we set and the resources we commit rather than remaining aspirations."},{"t":726,"topic":"Guyana biodiversity","text":"The SDGs must not only guide our ambitions, they must shape our choices and our national priorities. In we have made significant advances, including universal health care, free education, modern infrastructure, accelerated access to affordable housing, opportunities for full employment, acceleration of financing for small and medium-siz enterprises, and digitizing service delivery. Mr. President, two years ago at this very podium, I committed Guyana to provide global leadership on biodiversity. In July 2025, under Guyana's leadership, the Global Biodiversity Alliance was established as an inclusive platform. In just one year, the alliance expanded from 17 to 138 members, bringing together governments, institutional including the UN, development banks, indigenous peoples, local communities, scientists, universities, and the private sector."},{"t":803,"topic":"UN reform","text":"The second conference of the of the alliance to be held in October 2026 will begin to mobilize the resources and partnerships to deliver its ambitions. At the same time, we continue to advance our lowcarbon development strategy focused on turning forest stewardship and climate action into a new model for sustainable development. Mr. President, as we commence this 81st session, we have the opportunity to build a United Nations that is truly fit for purpose. The crisis confronting multilateralism can become the catalyst for its renewal. The United Nations must not be a monument to the past. It must become an instrument for the future. We need a security council that reflects the geopolitical realities of the 21st century, not the power structures of A council that embraces the emerg the emerging multipolarity of our world, including permanent representation from Africa and Latin America and the Mr."},{"t":884,"topic":"Multilateralism","text":"Mr. President, if the United Nation is to remain humanity's best hope, then this is not the hour to retreat from This is the hour to reclaim and to renew it. For it is in times such as these, when wars rage across borders, when the shadow of existential threats falls across the future of human civilization, when the old certinities are dissolving before our eyes, that multilateralism must rise. Multilateralism rests upon the proposition that our destinies are bound together. That the security of one, the security of one cannot be at the insecurity of another. And that in an interependent world, cooperation is a necessity. and where there can be no enduring prosperity when inequality depend deepens and no just international order when rules are applied selectively."},{"t":956,"topic":"UN reform","text":"It is to that truth that this 81st session of the general assembly must recommit itself. But recommmitment cannot mean merely repeating the language of yesterday. The world has changed and multilateralism must change with it. We need a new and invigorated multilateralism. One equal to the turbulence of our age. Sufficiently courageous to confront its trials, sufficiently to navigate its transformations, and sufficiently principled to defend the rule of international law. To make the United Nations fit for purpose, we must make it more transparent, accountable, and responsive. We must strengthen the General Assembly and give great and give greater weight to its deliberative and representative authority."},{"t":1021,"topic":"UN reform","text":"We must bring greater coherence to a system too often divided by institutional rivalries, bureaucratic silos, and competing mandates. We must ensure that the resources of the UN match the responsibilities we have entrusted to But institutions do not reform They require leadership capable of seeing beyond the present and imagining the institutions the future demands. The United Nations needs leadership that can bring its different organs, agencies, and programs into greater unity of purpose. Leadership that can build bridges where division has become habitual. Leadership that can defend the principles of the charter without fear or favor. The United Nations needs its next general secretary to work with all member states to restore confidence in the organization, mobilize its energies and turn the language of multilateralism from aspiration into action."},{"t":1096,"topic":"UN leadership","text":"The reform of the United Nations, the restoration of trust and the need to manage transformation is therefore inseparable from the question of leadership. And the choice of its next secretary general will be in no small measure a choice about the kind of United Nations we wish to leave to the generations that follow. It is in this spirit that Guyana has put forward the candidature of our excellency Carlin Rodrig Burke for the office of secretary general of the United Nations. She has served her represented the developing world, and worked within the multilateral system with a deep understanding of both its promise and its imperfections."},{"t":1161,"topic":"UN leadership","text":"We believe that her experience, her convictions, her record of service speak directly to the kind of leadership this moment demands. Her candidature therefore requires special significance amid the profound challenges confronting the United Nations and its national order. We need leadership capable of restoring trust without compromising principles, of listening without surrendering conviction, of building bridges across the widening chasms between north and south, between large states and small, between the developed and developing worlds. We need a secretary general who will defend the charter not only when it is politically convenient but precisely when its principles are under pressure. On a personal note, Mr. President Carolyn Rodrig Burket from every experience."},{"t":1231,"topic":"Indigenous rights","text":"Her very cross every struggle, every aspect of her accomplishment define and broke barriers. an indigenous woman coming from a small indigenous village defying the odds, the odds against persons, the odds against women, the odds against poverty. defining every challenge and rising to the top amidst those challenge. Her character is built on struggle, sacrifice, Her accomplishments are crafted in her humanity. This is an individual of extreme qualities."},{"t":1297,"topic":"UN leadership","text":"Not because she's a gy, not because she come from Guyana, but because I know personally and many of you know this too. The permanent representatives sitting here in New York. You know her character. You know her integrity. You know her will. You know her commitment. You know her love for humanity. You know her love for this world. And I know that this world will be a better place with Carlin Rodrig as the Secretary General of the United Nations. In the humblest of ways, I call on the P5, the Security Council, and every member and every member here to look beyond the small country that nominated her."},{"t":1360,"topic":"UN leadership","text":"Look beyond the small country that nominated her. Caricom as a body has endorsed her and let us rise to the challenge of giving this indigenous woman the chance of helping us craft together the United Nations we want to see succeed. The responsibility for recommending the next secretary general rests in the forest instance with the security council and we therefore respectfully place before its members the candidature of Carllin Rodrig Burke endorsed by the Caribbean community. We invite all to consider her candidacy on its merits and to judge whether her vision, experience, expertise, and record can help restore confidence in the United Nations at this critical moment."},{"t":1426,"topic":"Multilateralism","text":"Mr. President, the United Nations was conceived in hope and that hope remains alive in the pursuit of peace, security, and human progress over the perpetuation of division and war. This is why we must not abandon multilateralism because it is imperfect. We must renew it because humanity still needs it. Let us therefore build a United Nations that does not merely reflect the world as it is, but help create the world as it ought to be. A world where law restrains power, cooperation overcomes division, and every human being can look to the future with hope. Guyana believes that the choice remains ours as to whether the divisions of our age will define the future or whether nations can summon the will to build a more peaceful, secure, and prosperous international order."},{"t":1488,"topic":null,"text":"The United Nations must be at the heart of that endeavor. Not as an institution looking back at the world it was created to serve, but as one helping humanity shape the world that is yet to come. May God bless all of you. May God bless our humanity. May God guide us to peace and keep our world safe, our children safe, and give us all the where it all to build nations that are prosperous. I thank you and God bless you. On behalf of the assembly, I wish to thank the president of the Cooperative Republic of Guyana. No."}],"compare":[{"topic":"UN & its reform","share":0.4616,"mean":0.2034,"rank":11,"others":170},{"topic":"International Law & Order","share":0.1362,"mean":0.06,"rank":28,"others":102},{"topic":"Cuba","share":0.0622,"mean":0.0111,"rank":16,"others":23},{"topic":"Venezuela","share":0.0523,"mean":0.0048,"rank":9,"others":11},{"topic":"Sustainable Development","share":0.0481,"mean":0.0123,"rank":24,"others":28},{"topic":"Regional Security","share":0.0472,"mean":0.0044,"rank":10,"others":12},{"topic":"Human Rights","share":0.0464,"mean":0.0084,"rank":19,"others":24},{"topic":"Artificial Intelligence","share":0.0459,"mean":0.0505,"rank":82,"others":83}]};
